#!/usr/bin/env node
/**
 * Embed the finance admin app (src/plugins/finance/admin/app.client.js) into a
 * TypeScript module as a string.
 *
 * The plugin hands its admin script to the platform as text. Importing the .js
 * with Vite's `?raw` works in the Astro build but not in the esbuild bundles
 * the test suite makes of src/plugins, so the text is generated into a plain
 * module instead and committed. `--check` fails when the generated file is
 * stale — tests/finance.test.mjs runs it.
 *
 *   node scripts/build-finance-admin.mjs          # regenerate
 *   node scripts/build-finance-admin.mjs --check  # verify
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.join(root, 'src/plugins/finance/admin/app.client.js');
const out = path.join(root, 'src/plugins/finance/admin/app-script.ts');

const body = fs.readFileSync(src, 'utf8');
const generated = `// GENERATED by scripts/build-finance-admin.mjs from app.client.js — do not edit.\n`
  + `// Edit app.client.js, then run: node scripts/build-finance-admin.mjs\n`
  + `const script: string = ${JSON.stringify(body)};\nexport default script;\n`;

if (process.argv.includes('--check')) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (current !== generated) {
    console.error('✗ src/plugins/finance/admin/app-script.ts is stale — run: node scripts/build-finance-admin.mjs');
    process.exit(1);
  }
  console.log('✓ finance admin script is up to date');
} else {
  fs.writeFileSync(out, generated);
  console.log(`wrote ${path.relative(root, out)} (${body.length} chars)`);
}
